import{B,C,read,beadMolecule,circle}from'../ten-utils.js';
export default({g,p,extra,t,low})=>{let mode=extra.mode??0;
 if(mode===0){let a=p[0];for(let i=0;i<a;i++)beadMolecule(g,-1.2+(i%2)*.5,-.65+Math.floor(i/2)*.55,0,[[0,0,0,'H'],[.18,0,0,'H']],[[0,1]]);beadMolecule(g,-.55,.65,0,[[0,0,0,'O'],[.22,0,0,'O']],[[0,1]]);for(let i=0;i<2;i++)beadMolecule(g,.8,i*.65-.35,0,[[0,0,0,'O'],[-.15,.14,0,'H'],[.15,.14,0,'H']],[[0,1],[0,2]]);g.arrow([-.2,0,0],[.4,0,0]);g.text(0,-1.15,0,B(`${a}H2 + O2 → 2H2O`,`${a}H2 + O2 → 2H2O`));return[read('H atoms: left / right','H परमाणु: बायाँ / दायाँ',`${2*a} / 4`),read('O atoms: left / right','O परमाणु: बायाँ / दायाँ','2 / 2'),read('Equation','समीकरण',a===2?B('Balanced','संतुलित'):B('Not balanced','असंतुलित'))]}
 if(mode===1){let k=extra.type??0,f=p[0]/100;if(k===0){g.sphere(-1.2,-.25,0,.16,C.gold,'A');g.sphere(-.65,.25,0,.14,C.blue,'B')}else if(k===1){g.sphere(-1,-.1,0,.16,C.gold,'A');g.sphere(-.75,-.1,0,.14,C.blue,'B');g.line([-1,-.1,0],[-.75,-.1,0])}else if(k===2){g.sphere(-1.3,-.3,0,.16,C.gold,'A');g.sphere(-1,.3,0,.14,C.blue,'B');g.sphere(-.75,.3,0,.14,C.green,'C');g.line([-1,.3,0],[-.75,.3,0])}else{for(let i=0;i<8;i++)g.sphere(-1.15+(i%2)*.35,-.5+Math.floor(i/2)*.3,0,.06,i%2?C.blue:C.gold)}g.arrow([-.1,0,0],[.4,0,0]);let titles=[B('Combination: A + B → AB','संयोजन: A + B → AB'),B('Decomposition: AB → A + B','अपघटन: AB → A + B'),B('Displacement: A + BC → AC + B','विस्थापन: A + BC → AC + B'),B('Precipitation: ions → insoluble solid','अवक्षेपण: आयन → अघुलनशील ठोस')];if(k===0){g.sphere(.9,.1,0,.16,C.gold);g.sphere(1.2-.22*f,.1,0,.14,C.blue);g.line([.9,.1,0],[1.2-.22*f,.1,0])}else if(k===1){g.sphere(.8-.25*f,0,0,.16,C.gold);g.sphere(1+.3*f,0,0,.14,C.blue)}else if(k===2){g.sphere(.9,0,0,.16,C.gold);g.sphere(1.15,0,0,.15,C.green);g.sphere(.7,.55*f,0,.14,C.blue)}else{g.box(1,0,0,.4,.65,.3);for(let i=0;i<8;i++)g.sphere(.75+(i%4)*.16,(Math.floor(i/4)*.5-.3)*(1-f)+.5*f,0,.045,i%2?C.blue:C.gold)}g.text(0,-1.1,0,titles[k]);return[read('Selected reaction','चुनी अभिक्रिया',titles[k]),read('Illustrative progress','सांकेतिक प्रगति',p[0],'%')]}
 let wet=extra.water??1,air=extra.oxygen??1,rust=wet&&air?p[0]/10:0;g.box(0,0,0,.8,.14,.2,C.dark);for(let i=0;i<30*rust;i++){let a=i*2.4;g.sphere(Math.cos(a)*.7,Math.sin(a)*.08-.15,Math.sin(i)*.15,.05,'#c68960')}if(wet)for(let i=0;i<6;i++)g.sphere(-.8+i*.32,.8-((t+i*.2)%1)*.6,0,.04,C.blue);g.text(0,-.8,0,B('Iron + water + oxygen → rust','लोहा + जल + ऑक्सीजन → जंग'));return[read('Water present','जल उपस्थित',wet?B('Yes','हाँ'):B('No','नहीं')),read('Oxygen present','ऑक्सीजन उपस्थित',air?B('Yes','हाँ'):B('No','नहीं')),read('Illustrative rust coverage','सांकेतिक जंग आवरण',Math.round(rust*100),'%')]};
